<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {paperApi,paperRefresh,paperDiagnose} from './server-paper-client.js'
import {paperMetrics,paperSizingPreview} from './server-paper-model.js'
const props=defineProps({selectedId:{type:String,default:''}}),emit=defineEmits(['access-revoked'])
const rows=ref([]),item=ref(null),events=ref([]),error=ref(''),notice=ref(''),busy=ref(false),creating=ref(false),editing=ref(false),secretUrl=ref(''),reveal=ref(false)
const connection=ref(null),refreshError=ref(''),diagnostic=ref(null)
const draft=ref({name:'',description:'',entry:'',exit:'',initial_cash:1000}),setting=ref({name:'',description:'',entry:'',exit:'',mode:'fixed_notional',value:10})
let timer,disposed=false,loading=false
const current=computed(()=>item.value),metrics=computed(()=>paperMetrics(current.value)),preview=computed(()=>paperSizingPreview(current.value,setting.value.mode,setting.value.value))
const fmt=(n,d=4)=>n===null||n===undefined?'확인 전':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:d}),when=n=>n?new Date(n).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'실행 전'
const label={LONG_ENTRY:'Long 진입',SHORT_ENTRY:'Short 진입',LONG_EXIT:'Long 청산',SHORT_EXIT:'Short 청산'},state={queued:'처리 대기',awaiting_exit:'기존 청산 대기',filled:'가상 체결',ignored:'건너뜀',expired:'진입 만료',error:'오류'}
const split=v=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,40)
const executionLocked=computed(()=>!!current.value&&(current.value.auto_entries||Number(current.value.qty)!==0||events.value.some(e=>['queued','awaiting_exit'].includes(e.state))))
const executionChanged=computed(()=>{const x=current.value,s=setting.value;return !!x&&(JSON.stringify(split(s.entry))!==JSON.stringify(x.entry_conditions)||JSON.stringify(split(s.exit))!==JSON.stringify(x.exit_conditions)||s.mode!==x.sizing_mode||Number(s.value)!==Number(x.sizing_value))})
const connectionView=computed(()=>{
 const x=current.value||{},c=connection.value||{},h=c.health||x.connection_health||{},issued=c.webhook_issued??x.webhook_issued??false,count=Number(c.signal_count||0),qt=Number(h.quote_at_ms||x.quote?.at_ms||0);
 return {issued,revision:c.webhook_revision??x.webhook_revision,count,last:c.last_received_at,
 webhook:issued?'발급됨':'미발급',signal:count?'신호 수신 확인':'실제 신호 수신 대기',
 executor:h.code==='PROCESSING_FAILED'||c.latest_state==='error'?'처리 오류':x.auto_entries?'신규 진입 허용':'신규 진입 중지',
 quote:h.code&&h.code!=='OK'?'오류':qt?(Date.now()-qt<15000?'정상':'지연'):'확인 전',quoteAt:qt,
 healthError:h.code==='DEMO_QUOTE_FAILED'?'Demo 시세 조회 실패':h.code==='PROCESSING_FAILED'?'서버 처리 실패':'',lastError:c.last_error}
})
async function api(a,p){try{return await paperApi(a,p)}catch(e){if(e.accessDenied){rows.value=[];item.value=null;events.value=[];connection.value=null;secretUrl.value='';emit('access-revoked')}throw e}}
function syncSetting(){const x=item.value;if(!x)return;setting.value={name:x.name,description:x.description,entry:x.entry_conditions.join('\n'),exit:x.exit_conditions.join('\n'),mode:x.sizing_mode,value:Number(x.sizing_value)}}
async function load(){if(disposed||loading)return;loading=true;try{if(props.selectedId){const r=await api('get',{id:props.selectedId});if(!disposed){item.value=r.item;events.value=r.events;connection.value=r.connection||null;if(!editing.value)syncSetting()}}else{const r=await api('list');if(!disposed)rows.value=r}}catch(e){if(!disposed)error.value=e.message}finally{loading=false}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function create(){await run(async()=>{const d=draft.value;if(!d.name.trim()||d.description.length>200||!Number.isFinite(Number(d.initial_cash))||d.initial_cash<10||d.initial_cash>1000000)throw Error('이름·설명 200자·가상 잔고 10~1,000,000을 확인해 주세요.');const r=await api('create',{name:d.name,description:d.description,initial_cash:Number(d.initial_cash),entry_conditions:split(d.entry),exit_conditions:split(d.exit)});creating.value=false;location.hash='auto-trading?paper='+r.id})}
async function save(){await run(async()=>{const s=setting.value,changed=executionChanged.value;if(!s.name.trim()||s.description.length>200||!preview.value)throw Error('이름·설명·투자금 범위를 확인해 주세요.');await api('save',{id:current.value.id,version:current.value.config_version,name:s.name,description:s.description,entry_conditions:split(s.entry),exit_conditions:split(s.exit),sizing_mode:s.mode,sizing_value:Number(s.value)});editing.value=false;if(changed)secretUrl.value='';notice.value=changed?'실행 설정을 저장했습니다. 변경된 조건에 맞는 전용 Webhook과 새 알림이 필요합니다.':'이름·설명을 저장했습니다. 기존 Webhook 주소와 실행 설정은 유지됩니다.'})}
async function action(a){await run(async()=>{const x=current.value;await api(a,{id:x.id,request_id:crypto.randomUUID(),expected_entry:x.entry_event,expected_qty:String(x.qty)});if(a!=='stop'){const out=await paperRefresh(x.id);refreshError.value=out.error||''}else notice.value='신규 자동 진입을 중지했습니다. 보유 청산 신호는 처리합니다.'})}
async function refresh(){await run(async()=>{const out=await paperRefresh(current.value.id);refreshError.value=out.error||''})}
async function checkConnection(){await run(async()=>{diagnostic.value=await paperDiagnose(current.value.id);refreshError.value=diagnostic.value.error||'';if(!diagnostic.value.error)notice.value='관리자 권한·서버 응답·Demo 시세를 확인했습니다. 주문은 만들지 않았습니다. TradingView 연결은 실제 신호 수신으로 별도 확인합니다.'})}
async function webhook(){await run(async()=>{const r=await api('webhook',{id:current.value.id});secretUrl.value='https://wkpoervofwniizdcklre.supabase.co/functions/v1/auto-trading-paper/tv/'+r.item.id+'/'+r.revision+'/'+r.secret;reveal.value=false;notice.value='전용 주소를 발급했습니다. 기존 주소는 무효입니다. 주소는 이 화면에서만 복사해 주세요.'})}
async function copy(){try{await navigator.clipboard.writeText(secretUrl.value);notice.value='Webhook 주소를 복사했습니다.'}catch{reveal.value=true;notice.value='주소를 직접 선택해 복사해 주세요.'}}
async function archive(){if(!confirm('이 서버 모의 거래를 보관할까요?'))return;await run(async()=>{await api('archive',{id:current.value.id});location.hash='auto-trading'})}
onMounted(()=>{load();timer=setInterval(async()=>{if(disposed||document.hidden||busy.value||loading)return;await load();const x=current.value;if(x?.data_enabled&&(x.auto_entries||Number(x.qty)!==0||events.value.some(e=>['queued','awaiting_exit'].includes(e.state)))){try{const out=await paperRefresh(x.id);if(!disposed){refreshError.value=out.error||'';await load()}}catch(e){if(!disposed)refreshError.value=e.message}}},5000)})
onUnmounted(()=>{disposed=true;clearInterval(timer);secretUrl.value=''})
</script>
<template><section class="paper-lab" aria-label="PC 독립 서버 모의 거래"><div class="paper-banner"><span>SERVER PAPER</span><strong>PC가 꺼져도 동작하는 서버 모의 거래</strong><p>Demo 시세로 가상 장부만 체결합니다. Binance Demo 계좌 주문·잔고와 구분됩니다. 휴대폰에서 수동 진입·청산과 자동 신호 허용을 결정할 수 있습니다.</p></div>
<p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="!selectedId"><div class="paper-head"><h2>독립 전략 실험실</h2><button type="button" :disabled="busy" @click="creating=!creating">{{creating?'등록 접기':'서버 모의 전략 만들기'}}</button></div>
<form v-if="creating" class="paper-form" @submit.prevent="create"><h3>독립 가상 잔고를 가진 새 전략</h3><label>거래 이름<input v-model="draft.name" maxlength="160" required></label><label>설명 ({{draft.description.length}}/200자)<textarea v-model="draft.description" maxlength="200"></textarea></label><div class="paper-grid"><label>진입 조건 (항목마다 줄 바꿈)<textarea v-model="draft.entry"></textarea></label><label>청산 조건 (항목마다 줄 바꿈)<textarea v-model="draft.exit"></textarea></label></div><label>시작 가상 잔고 (USDT)<input v-model.number="draft.initial_cash" type="number" min="10" max="1000000" required></label><p>SOXLUSDT.P 10초 신호와 SOXLUSDT Demo 시세를 사용합니다. 조건 이름은 기록용이며 지표 설정을 바꾸지 않습니다. 기본 진입 총액 10 USDT, 가상 30배, 가상 수수료 0.04%입니다.</p><button :disabled="busy">가상 전략 생성</button><button type="button" @click="creating=false">취소</button></form>
<div class="paper-table"><table><thead><tr><th>거래 이름</th><th>진입 조건</th><th>청산 조건</th><th>실행</th><th>보유</th><th>가상 지갑</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><a :href="'/admin/#auto-trading?paper='+x.id">{{x.name}}</a><small>서버 가상 장부 · 설정 v{{x.config_version}}</small></td><td><div v-for="(c,n) in x.entry_conditions" :key="n">{{c}}</div></td><td><div v-for="(c,n) in x.exit_conditions" :key="n">{{c}}</div></td><td>{{x.auto_entries?'자동 진입 허용':'자동 진입 중지'}}</td><td>{{Number(x.qty)>0?'Long':Number(x.qty)<0?'Short':'미보유'}}</td><td>{{fmt(x.wallet)}} USDT</td></tr></tbody></table></div><p v-if="!rows.length&&!error">아직 서버 모의 전략이 없습니다. 전략별 잔고와 포지션은 서로 섞이지 않습니다.</p></template>
<template v-else-if="current"><h2>{{current.name}}</h2><p>SOXLUSDT · 10초 · 설정 v{{current.config_version}} · 가상 30배</p><div class="paper-status"><strong>{{Number(current.qty)>0?'Long 보유':Number(current.qty)<0?'Short 보유':'미보유'}}</strong><span>{{current.auto_entries?'자동 진입 허용':'자동 진입 중지'}}</span><span>{{current.reason}}</span></div>
<div class="paper-connection" aria-label="자동 거래 연결 상태"><article><small>Webhook</small><strong>{{connectionView.webhook}} · 버전 {{connectionView.revision}}</strong></article><article><small>TradingView</small><strong>{{connectionView.signal}}</strong><span>{{connectionView.count}}건 · {{connectionView.last?when(connectionView.last):'아직 실제 신호 없음'}}</span></article><article><small>실행기</small><strong>{{connectionView.executor}}</strong></article><article><small>Demo 시세</small><strong>{{connectionView.quote}}</strong><span>{{connectionView.quoteAt?when(connectionView.quoteAt):'시세 확인 전'}}</span></article></div>
<p v-if="connectionView.issued&&!connectionView.count" class="paper-waiting">주소 발급 완료 · 실제 신호 수신 대기. TradingView 알림에 이 거래의 전용 주소를 넣었는지 확인해 주세요.</p><p v-else-if="!connectionView.issued" class="paper-waiting">전용 Webhook이 필요합니다. 아래 ‘TradingView 서버 신호 연결’에서 주소를 발급해 주세요.</p>
<p v-if="refreshError||connectionView.healthError" role="alert">{{refreshError||connectionView.healthError}} · 기존 신호와 포지션 기록은 유지됩니다.</p><p v-if="connectionView.lastError">최근 처리 오류: {{connectionView.lastError.message}} · {{when(connectionView.lastError.at)}}</p>
<button type="button" :disabled="busy" @click="checkConnection">연결 점검 · 주문 없음</button><p>연결 점검은 관리자 권한·서버 응답·Demo 시세만 확인합니다. TradingView 실제 신호 수신이나 진입·청산을 대신하지 않습니다.</p>
<div v-if="current.data_enabled" class="paper-cards"><article><small>현재 미실현 수익금</small><b :class="{'positive':metrics.pnl>0,'negative':metrics.pnl<0}">{{fmt(metrics.pnl)}} USDT</b><span>증거금 대비 {{fmt(metrics.roi,2)}}%</span></article><article><small>투입 원금 (가상 진입 증거금)</small><b>{{fmt(metrics.margin)}} USDT</b><span>포지션 수량 {{fmt(current.qty)}}</span></article><article><small>가상 지갑 / 평가 자산</small><b>{{fmt(current.wallet)}} USDT</b><span>평가 {{fmt(metrics.equity)}} USDT</span></article><article><small>가상 실현 순손익</small><b>{{fmt(metrics.net)}} USDT</b><span>진입·청산 가상 수수료 반영</span></article></div><p v-else>실행 전입니다. 진입 시작 또는 수동 진입·청산을 실행하면 거래 데이터를 불러옵니다.</p>
<p v-if="current.data_enabled">진입가 {{fmt(current.entry_price)}} / Demo 기준가 {{fmt(current.quote?.price)}} · 시세 시각 {{when(current.quote?.at_ms)}} <strong v-if="Number(current.qty)&&!metrics.fresh">시세 확인 필요</strong></p>
<div class="paper-controls"><button type="button" :disabled="busy||current.auto_entries" @click="action('start')">진입 시작</button><button type="button" :disabled="busy||!current.auto_entries" @click="action('stop')">신규 자동 진입 중지</button><button type="button" :disabled="busy||Number(current.qty)!==0||current.auto_entries" @click="action('long')">수동 Long 모의 진입</button><button type="button" :disabled="busy||Number(current.qty)!==0||current.auto_entries" @click="action('short')">수동 Short 모의 진입</button><button type="button" :disabled="busy||Number(current.qty)===0" @click="action('close')">모의 청산 · 자동 진입 중지</button><button type="button" :disabled="busy||!current.data_enabled" @click="refresh">시세·처리 결과 확인</button></div>
<p>진입 시작은 이후의 새 TradingView 신호만 허용합니다. 차트의 과거 진입을 따라 즉시 주문하지 않습니다. 수동 진입은 자동 진입 중지·미보유 상태에서 실행합니다.</p>
<details class="paper-form" :open="editing"><summary @click.prevent="editing=!editing">요약 및 설정 {{editing?'접기':'펼치기'}}</summary><form v-if="editing" @submit.prevent="save"><label>거래 이름<input v-model="setting.name" maxlength="160" required></label><div class="paper-grid"><label>진입 조건<textarea v-model="setting.entry" :disabled="executionLocked"></textarea></label><label>청산 조건<textarea v-model="setting.exit" :disabled="executionLocked"></textarea></label></div><label>설명 ({{setting.description.length}}/200자)<textarea v-model="setting.description" maxlength="200"></textarea></label><label>다음 진입 투자금<select v-model="setting.mode" :disabled="executionLocked"><option value="fixed_notional">주문 총액 (USDT)</option><option value="available_percent">사용 가능한 가상 잔고 비율 (%)</option></select></label><label v-if="setting.mode==='available_percent'">사용 비율 {{setting.value}}%<input v-model.number="setting.value" :disabled="executionLocked" type="range" min="0" max="100" step="0.5"></label><label>{{setting.mode==='available_percent'?'비율 (%)':'주문 총액 (USDT)'}}<input v-model.number="setting.value" :disabled="executionLocked" type="number" min="0.0001" :max="setting.mode==='available_percent'?100:100000" step="any" required></label><p v-if="preview">예상 총액 {{fmt(preview.notional)}} / 증거금 {{fmt(preview.margin)}} / 진입 수수료 {{fmt(preview.fee)}} USDT. 실제 가상 수량은 처리 시 Demo 시세와 수량 단위로 내립니다.</p><p>이름·설명만 저장하면 기존 Webhook 주소와 설정 버전이 유지됩니다. 조건·투자금 변경은 중지·미보유 상태에서 저장하며 기존 주소가 무효가 됩니다.</p><button :disabled="busy||(executionChanged&&executionLocked)">이름·설명·설정 저장</button><button type="button" @click="editing=false;syncSetting()">취소</button><button type="button" :disabled="busy||current.auto_entries||Number(current.qty)!==0" @click="archive">보관</button></form></details>
<details class="paper-form"><summary>TradingView 서버 신호 연결</summary><p>새 전략 전용 주소입니다. 현재 PC Demo 알림을 재사용하거나 변경하지 않습니다. 기존 지표의 JSON alert() 호출을 사용하되 같은 설정 조합의 전용 알림을 새로 만드세요. 앱·팝업·이메일·소리는 끄고 Webhook만 켭니다.</p><p v-if="connectionView.issued">전용 주소 발급됨 · 버전 {{connectionView.revision}}. 주소 복사는 발급 직후 이 화면에서만 가능합니다. 재발급하면 기존 주소가 즉시 무효가 되며 TradingView 알림 주소도 바꿔야 합니다.</p><p v-if="executionLocked">주소 재발급은 자동 진입 중지·미보유 상태에서 가능합니다.</p><button type="button" :disabled="busy||executionLocked" @click="webhook">{{connectionView.issued?'전용 Webhook 주소 재발급':'전용 Webhook 주소 발급'}}</button><div v-if="secretUrl"><label>전용 주소<input :type="reveal?'text':'password'" :value="secretUrl" readonly autocomplete="off"></label><label><input v-model="reveal" type="checkbox">주소 표시</label><button type="button" @click="copy">주소 복사</button></div><p>조건: SOXL 통합 지표 v0.12 → 어떤 alert() 함수 호출 → 10초. 알림 생성 이후 차트 설정 변경은 서버 알림에 자동 반영되지 않습니다. 실제 신호 수신 전에는 연결 검증 완료로 표시하지 않습니다.</p></details>
<h3>신호 → 가상 주문 → 포지션 변화</h3><div class="paper-table"><table><thead><tr><th>수신 시각</th><th>신호 / 출처</th><th>처리</th><th>가상 주문 / 변화</th><th>설명</th></tr></thead><tbody><tr v-for="e in events" :key="e.seq"><td>{{when(e.received_at)}}</td><td>{{label[e.event]}} / {{e.source==='manual'?'모바일·웹 수동':'TradingView 수신'}}<details><summary>신호 ID</summary>{{e.event_id}}</details></td><td>{{state[e.state]}}</td><td>{{e.fill?.paper_order_id||'—'}}<small v-if="e.fill">{{e.fill.before_qty}} → {{e.fill.after_qty}} / {{e.fill.price}} USDT</small></td><td>{{e.note}}</td></tr><tr v-if="!events.length"><td colspan="5">아직 수신·수동 실행 기록이 없습니다. 주소 발급과 실제 TradingView 신호 수신은 별도 단계입니다.</td></tr></tbody></table></div><p>가상 체결은 Demo 기준가를 사용하며 호가 슬리피지·펀딩·강제 청산은 모사하지 않습니다. 결과를 Binance Demo/실거래 수익과 동일하게 해석하지 마세요.</p></template>
